package fraymus.workspace;

import org.json.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Atomic, cross-process compare-and-set revisions. A pending goal owns the uncommitted world. */
final class WorldLedger {
    static final String LEGACY_093="c140c939ba0c64a145faf1c41e5475d2f3d0984aa6ff92bc1c131ea31a167958";
    static final String LEGACY_084="b4e44566e392b3e1278e075c36e38a92ad9c0e62bc24c442c5074b0fbaf4d32d";
    static final int MAX_WORLDS=32;
    static final String LEGACY_078="8ea29b75d4d4d6a0a1bdfd68e693a01b93647536eaa7cf7be28db82d6d4c5372";
    static final String VERSION="persistent-world-ledger-035-v1";
    private final Path file,lock;
    WorldLedger(Path project) throws Exception {file=project.resolve("persistent-worlds/state.json");lock=file.resolveSibling("state.lock");access(false,data->null);}
    private interface Tx<T>{T apply(JSONObject data) throws Exception;}
    private synchronized <T>T access(boolean write,Tx<T> tx) throws Exception {
        Files.createDirectories(file.getParent());
        try(var channel=FileChannel.open(lock,StandardOpenOption.CREATE,StandardOpenOption.WRITE);var held=channel.lock()){
            JSONObject data;
            if(Files.exists(file)){
                if(Files.size(file)>16_000_000)throw new IllegalStateException("World ledger exceeds16MB");
                var envelope=new JSONObject(Files.readString(file));data=envelope.getJSONObject("payload");
                if(!envelope.getString("version").equals(VERSION)||!envelope.getString("sha256").equals(WorldFrames.hash(data)))throw new IllegalStateException("World ledger checksum/version mismatch; original bytes preserved");
            }else data=new JSONObject().put("worlds",new JSONArray());
            validate(data);T out=tx.apply(data);
            if(write){validate(data);var envelope=new JSONObject().put("version",VERSION).put("payload",data).put("sha256",WorldFrames.hash(data));byte[] bytes=envelope.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>16_000_000)throw new IllegalStateException("World ledger capacity reached");var pending=file.resolveSibling("state.pending.json");try(var staging=FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())staging.write(buffer);staging.force(true);}Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
            return out;
        }
    }
    private static JSONObject world(JSONObject data,String id){UUID.fromString(id);for(Object raw:data.getJSONArray("worlds")){var w=(JSONObject)raw;if(w.getString("id").equals(id))return w;}throw new IllegalArgumentException("Unknown persistent world");}
    private static JSONObject head(JSONObject w){var rs=w.getJSONArray("revisions");return rs.getJSONObject(rs.length()-1);}
    private static void validate(JSONObject data){
        SpatialScene.keys(data,"worlds");if(data.getJSONArray("worlds").length()>MAX_WORLDS)throw new IllegalStateException("World history capacity"+MAX_WORLDS+" reached");var ids=new HashSet<String>();
        for(Object raw:data.getJSONArray("worlds")){
            var w=(JSONObject)raw;UUID.fromString(w.getString("id"));if(!ids.add(w.getString("id"))||!Set.of(WorldNativeCheckpoint.identity(),LEGACY_093,LEGACY_084,LEGACY_078,Construction051.LEGACY_050,Construction054.LEGACY_053,Construction055.LEGACY_054,Design056.LEGACY_055,SupportDesign059.LEGACY_058,SupportRepair060.LEGACY_059).contains(w.getString("codeSha256")))throw new IllegalStateException("World identity/native code changed");var rs=w.getJSONArray("revisions");if(rs.isEmpty()||rs.length()>64)throw new IllegalStateException("World revision bounds changed");String parent="";JSONObject original=null;
            for(int i=0;i<rs.length();i++){
                var rev=rs.getJSONObject(i);var unsigned=WorldFrames.copy(rev);unsigned.remove("hash");if(rev.getInt("revision")!=i||!rev.getString("parentHash").equals(parent)||!rev.getString("hash").equals(WorldFrames.hash(unsigned)))throw new IllegalStateException("World revision chain changed");var frame=rev.getJSONObject("frame");WorldFrames.verify(frame);if(original==null)original=frame.getJSONObject("originalScene");else if(!original.similar(frame.getJSONObject("originalScene")))throw new IllegalStateException("World immutable source/IDs changed");
                switch(rev.getString("kind")){case "create"->{if(i!=0||frame.getLong("elapsedTicks")!=0)throw new IllegalStateException("Invalid world origin");}case "goal"->{UUID.fromString(rev.getString("goalId"));UUID.fromString(rev.getString("runId"));if(i==0||frame.getLong("elapsedTicks")<=rs.getJSONObject(i-1).getJSONObject("frame").getLong("elapsedTicks"))throw new IllegalStateException("World goal clock did not advance");}case "upgrade051"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(Construction051.LEGACY_050))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade094"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(LEGACY_093))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade085"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(LEGACY_084))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade079"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(LEGACY_078))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade060"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(SupportRepair060.LEGACY_059))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade059"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(SupportDesign059.LEGACY_058))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade056"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(Design056.LEGACY_055))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade055"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(Construction055.LEGACY_054))throw new IllegalStateException("Compatibility handoff changed the world");}case "upgrade054"->{if(i==0||!frame.similar(rs.getJSONObject(i-1).getJSONObject("frame"))||!rev.getString("previousCodeSha256").equals(Construction054.LEGACY_053))throw new IllegalStateException("Compatibility handoff changed the world");}case "restore"->{int target=rev.getInt("restoredRevision");if(target<0||target>=i||!frame.similar(rs.getJSONObject(target).getJSONObject("frame")))throw new IllegalStateException("Explicit restored world differs from selected revision");}default->throw new IllegalStateException("Unknown world revision kind");}parent=rev.getString("hash");
            }
            if(w.has("pending")){var p=w.getJSONObject("pending");UUID.fromString(p.getString("goalId"));UUID.fromString(p.getString("runId"));if(p.getInt("baseRevision")!=head(w).getInt("revision")||!p.getString("baseHash").equals(head(w).getString("hash")))throw new IllegalStateException("Pending world ownership lost its verified base");}
        }
    }
    private static void expect(JSONObject w,int revision,String hash){if(head(w).getInt("revision")!=revision||!head(w).getString("hash").equals(hash))throw new ConcurrentModificationException("Stale world revision/observation; observe and confirm the current world again");}
    private static JSONObject append(JSONObject w,String kind,JSONObject frame,JSONObject details){
        var revisions=w.getJSONArray("revisions");if(revisions.length()>=64)throw new IllegalStateException("World revision capacity64 reached");var rev=new JSONObject().put("revision",revisions.length()).put("parentHash",revisions.isEmpty()?"":head(w).getString("hash")).put("kind",kind).put("at",Instant.now()).put("frame",WorldFrames.copy(frame));for(String key:details.keySet())rev.put(key,details.get(key));rev.put("hash",WorldFrames.hash(rev));revisions.put(rev);return WorldFrames.copy(rev);
    }
    static JSONObject binding(JSONObject w){var h=head(w);return new JSONObject().put("worldId",w.getString("id")).put("expectedRevision",h.getInt("revision")).put("expectedHash",h.getString("hash"));}
    JSONObject create(JSONObject source,String title) throws Exception {if(title.isBlank()||title.length()>120)throw new IllegalArgumentException("World title needs1..120characters");var frame=WorldFrames.initial(source);return access(true,data->{var w=new JSONObject().put("id",UUID.randomUUID().toString()).put("title",title).put("codeSha256",WorldNativeCheckpoint.identity()).put("createdAt",Instant.now()).put("revisions",new JSONArray());append(w,"create",frame,new JSONObject());data.getJSONArray("worlds").put(w);return WorldFrames.copy(w);});}
    JSONArray list() throws Exception {return access(false,data->{var out=new JSONArray();for(Object raw:data.getJSONArray("worlds")){var w=(JSONObject)raw;var value=binding(w).put("title",w.getString("title")).put("elapsedTicks",head(w).getJSONObject("frame").getLong("elapsedTicks")).put("status",w.has("pending")?"owned":"verified");if(w.has("pending"))value.put("pending",WorldFrames.copy(w.getJSONObject("pending")));out.put(value);}return out;});}
    private static void current(JSONObject w){if(!w.getString("codeSha256").equals(WorldNativeCheckpoint.identity()))throw new IllegalStateException("This source-bound world needs an explicit compatible engine upgrade before new actuation");}
    JSONObject upgrade051(String id,int revision,String hash)throws Exception{return access(true,data->{var w=world(data,id);expect(w,revision,hash);if(w.has("pending"))throw new IllegalStateException("A pending owner must finish in its original engine before upgrade");if(w.getString("codeSha256").equals(WorldNativeCheckpoint.identity()))return binding(w);if(!Set.of(LEGACY_093,LEGACY_084,LEGACY_078,Construction051.LEGACY_050,Construction054.LEGACY_053,Construction055.LEGACY_054,Design056.LEGACY_055,SupportDesign059.LEGACY_058,SupportRepair060.LEGACY_059).contains(w.getString("codeSha256")))throw new IllegalStateException("Unknown legacy engine");var details=new JSONObject().put("previousCodeSha256",w.getString("codeSha256")).put("currentCodeSha256",WorldNativeCheckpoint.identity()).put("reason","Explicit compatible cold frame handoff; no simulated movement");append(w,w.getString("codeSha256").equals(LEGACY_093)?"upgrade094":w.getString("codeSha256").equals(LEGACY_084)?"upgrade085":w.getString("codeSha256").equals(LEGACY_078)?"upgrade079":w.getString("codeSha256").equals(SupportRepair060.LEGACY_059)?"upgrade060":w.getString("codeSha256").equals(SupportDesign059.LEGACY_058)?"upgrade059":w.getString("codeSha256").equals(Design056.LEGACY_055)?"upgrade056":w.getString("codeSha256").equals(Construction055.LEGACY_054)?"upgrade055":w.getString("codeSha256").equals(Construction054.LEGACY_053)?"upgrade054":"upgrade051",head(w).getJSONObject("frame"),details);w.put("codeSha256",WorldNativeCheckpoint.identity());return binding(w);});}
    JSONObject read(String id) throws Exception {return access(false,data->WorldFrames.copy(world(data,id)));}
    JSONObject observe(String id) throws Exception {return access(false,data->{var w=world(data,id);var result=binding(w).put("requiresUpgrade051",!w.getString("codeSha256").equals(WorldNativeCheckpoint.identity())).put("title",w.getString("title")).put("frame",WorldFrames.copy(head(w).getJSONObject("frame"))).put("status",w.has("pending")?"owned":"verified");if(head(w).has("construction051"))result.put("construction051",WorldFrames.copy(head(w).getJSONObject("construction051")));if(w.has("pending"))result.put("pending",WorldFrames.copy(w.getJSONObject("pending")));return result;});}
    JSONObject source(JSONObject binding) throws Exception {return access(false,data->{var w=world(data,binding.getString("worldId"));int revision=binding.getInt("expectedRevision");if(revision<0||revision>=w.getJSONArray("revisions").length())throw new IllegalStateException("World base revision missing");var rev=w.getJSONArray("revisions").getJSONObject(revision);if(!rev.getString("hash").equals(binding.getString("expectedHash")))throw new IllegalStateException("World base hash differs");return WorldFrames.scene(rev.getJSONObject("frame"));});}
    JSONObject preview(JSONObject args) throws Exception {return access(false,data->{var w=world(data,args.getString("worldId"));current(w);expect(w,args.getInt("expectedRevision"),args.getString("expectedHash"));if(w.has("pending"))throw new IllegalStateException("World has an uncommitted goal; Resume or explicitly restore it first");var scene=WorldFrames.scene(head(w).getJSONObject("frame"));return WorldPlan.build(scene,args.has("construction051")?Construction051.intent(scene,args.getJSONObject("construction051"),args.optDouble("forceLimitN",40),args.optDouble("torqueLimitNm",4)):WorldPlan.intent(scene,args.getJSONArray("targets"),args.optDouble("forceLimitN",60),args.optDouble("torqueLimitNm",4)));});}
    void reserve(JSONObject binding,String goalId,String runId,JSONObject plan) throws Exception {access(true,data->{var w=world(data,binding.getString("worldId"));current(w);expect(w,binding.getInt("expectedRevision"),binding.getString("expectedHash"));var lease=new JSONObject().put("goalId",goalId).put("runId",runId).put("baseRevision",binding.getInt("expectedRevision")).put("baseHash",binding.getString("expectedHash")).put("planSha256",WorldFrames.hash(plan)).put("status","owned");if(w.has("pending")){var p=w.getJSONObject("pending");for(String k:List.of("goalId","runId","baseRevision","baseHash","planSha256"))if(!new JSONObject().put("v",p.get(k)).similar(new JSONObject().put("v",lease.get(k))))throw new IllegalStateException("Another pending goal owns this world");return null;}WorldPlan.verify(WorldFrames.scene(head(w).getJSONObject("frame")),plan);w.put("pending",lease);return null;});}
    JSONObject committed(String id,String goalId) throws Exception {return access(false,data->{for(Object raw:world(data,id).getJSONArray("revisions")){var rev=(JSONObject)raw;if(rev.optString("goalId").equals(goalId))return WorldFrames.copy(rev);}return new JSONObject();});}
    JSONObject commit(JSONObject binding,String goalId,JSONObject run,JSONObject receipt,JSONObject report) throws Exception {
        var metrics=WorldVerify.verify(run);JSONObject construction=null;if(run.getJSONObject("plan").getJSONObject("intent").has("construction051")){construction=Construction051.verifyStructure(run);if(!construction.getBoolean("passed"))throw new IllegalStateException("Released bridge does not have verified stable support");}final JSONObject structure=construction;if(!metrics.getBoolean("passed")||!run.getString("status").equals("completed")||!run.getString("goalId").equals(goalId))throw new IllegalStateException("Only the owned independently verified native result may commit");
        if(!receipt.optBoolean("passed")||receipt.optInt("frames")!=6||receipt.optInt("cells")!=run.getJSONObject("plan").getJSONArray("orderedTargets").length()*5||!receipt.optString("dataSha256").equals(PushLearning.hash(WorldReport.data(run))))throw new IllegalStateException("Original actual world report receipt required");UUID.fromString(report.getString("id"));if(report.getInt("version")<1||!report.getString("sha256").matches("[a-f0-9]{64}"))throw new IllegalStateException("Original report binding required");
        return access(true,data->{var w=world(data,binding.getString("worldId"));String nativeHash=WorldFrames.hash(run);for(Object raw:w.getJSONArray("revisions")){var rev=(JSONObject)raw;if(rev.optString("goalId").equals(goalId)){if(!rev.getString("nativeCanonicalSha256").equals(nativeHash)||!rev.getJSONObject("report").similar(report))throw new IllegalStateException("Idempotent world commit evidence changed");return WorldFrames.copy(rev);}}
            expect(w,binding.getInt("expectedRevision"),binding.getString("expectedHash"));var p=w.getJSONObject("pending");if(!p.getString("goalId").equals(goalId)||!p.getString("runId").equals(run.getString("id"))||!p.getString("planSha256").equals(WorldFrames.hash(run.getJSONObject("plan"))))throw new IllegalStateException("World goal/run ownership changed");
            var frame=WorldFrames.after(head(w).getJSONObject("frame"),run);var rev=append(w,"goal",frame,new JSONObject().put("goalId",goalId).put("runId",run.getString("id")).put("nativeCanonicalSha256",nativeHash).put("metrics",metrics).put("receipt",receipt).put("report",report));if(structure!=null){var stored=head(w);stored.put("construction051",structure);stored.remove("hash");stored.put("hash",WorldFrames.hash(stored));rev=WorldFrames.copy(stored);}w.remove("pending");return rev;});
    }
    JSONObject commitProcedure079(WorldProcedure079 runner,String goalId,JSONObject receipt,JSONObject report)throws Exception {
        var j=runner.read(goalId);if(!j.getString("status").equals("ready"))throw new IllegalStateException("Procedure is not ready for commitment");var checked=runner.audit(goalId);var last=runner.last(goalId);var binding=j.getJSONObject("binding");String proof=WorldFrames.hash(j);
        if(!receipt.optBoolean("passed")||receipt.optInt("frames")!=6||receipt.optInt("cells")!=last.getJSONObject("plan").getJSONArray("orderedTargets").length()*5||!receipt.optString("dataSha256").equals(PushLearning.hash(WorldReport.data(last))))throw new IllegalStateException("Original final-stage canvas receipt required");UUID.fromString(report.getString("id"));if(report.getInt("version")<1||!report.getString("sha256").matches("[a-f0-9]{64}"))throw new IllegalStateException("Original report binding required");
        return access(true,data->{var w=world(data,binding.getString("worldId"));current(w);for(Object raw:w.getJSONArray("revisions")){var rev=(JSONObject)raw;if(rev.optString("goalId").equals(goalId)){if(!rev.optString("procedureCanonicalSha256").equals(proof)||!rev.getJSONObject("report").similar(report))throw new IllegalStateException("Idempotent procedure evidence changed");return WorldFrames.copy(rev);}}
            expect(w,binding.getInt("expectedRevision"),binding.getString("expectedHash"));if(!head(w).getJSONObject("frame").similar(j.getJSONObject("initialFrame")))throw new IllegalStateException("Procedure changed its initial world");var lease=w.getJSONObject("pending");if(!lease.getString("goalId").equals(goalId)||!lease.getString("runId").equals(goalId)||!lease.getString("planSha256").equals(WorldFrames.hash(j.getJSONObject("leasePlan"))))throw new IllegalStateException("Procedure lost world ownership");
            var details=new JSONObject().put("goalId",goalId).put("runId",last.getString("id")).put("nativeCanonicalSha256",WorldFrames.hash(last)).put("procedureCanonicalSha256",proof).put("procedure079",runner.summary(goalId)).put("receipt",receipt).put("report",report);
            var metrics=WorldFrames.copy(checked);metrics.remove("finalFrame");details.put("metrics",metrics);
            var rev=append(w,"goal",checked.getJSONObject("finalFrame"),details);w.remove("pending");return rev;
        });
    }
    JSONObject restore(String id,int revision,String hash,int target,String abandonedGoal) throws Exception {return access(true,data->{var w=world(data,id);expect(w,revision,hash);if(target<0||target>w.getJSONArray("revisions").length()-1)throw new IllegalArgumentException("Select an existing verified revision");if(w.has("pending")&&!w.getJSONObject("pending").getString("goalId").equals(abandonedGoal))throw new IllegalStateException("Explicitly abandon the owned goal before restoring its world");var details=new JSONObject().put("restoredRevision",target).put("reason","Explicit state restoration, not physical movement");if(w.has("pending"))details.put("abandonedGoalId",abandonedGoal).put("abandonedRunId",w.getJSONObject("pending").getString("runId"));var frame=w.getJSONArray("revisions").getJSONObject(target).getJSONObject("frame");var rev=append(w,"restore",frame,details);w.remove("pending");return rev;});}
}
